import json, re
from pathlib import Path
nb = json.loads(Path('/Users/sinchunyeung/github/image-inpainting/code.ipynb').read_text())
# Search for wandb key-like strings (32+ hex/alnum after common prefixes)
pat = re.compile(r'(WANDB_API_KEY\s*=\s*[^\s]+|api[_-]?key\s*[:=]\s*[^\s"\']+|["\'][a-f0-9]{32,}["\']|key-[A-Za-z0-9]{20,})', re.I)
hits = []
for i, cell in enumerate(nb.get('cells', [])):
    src = ''.join(cell.get('source', []))
    outs = []
    for o in cell.get('outputs', []) or []:
        if 'text' in o: outs.append(''.join(o['text']) if isinstance(o['text'], list) else o['text'])
        if 'data' in o:
            for v in o['data'].values():
                outs.append(''.join(v) if isinstance(v, list) else str(v))
    blob = src + '\n' + '\n'.join(outs)
    for m in pat.finditer(blob):
        snippet = m.group(0)[:80]
        hits.append((i, snippet))
print('pattern hits:', len(hits))
for h in hits[:30]:
    print(h)
# Also check if login was called with key= argument
for i, cell in enumerate(nb.get('cells', [])):
    src = ''.join(cell.get('source', []))
    if 'wandb.login' in src or 'api_key' in src.lower():
